/* moves[0..depth-1] are 1..9, and must already have survived pruning.
 * Compute once on entering a node; cache until that node is exhausted.
 * A set bit m rejects move m+1, including all same-face continuations.
 */
static unsigned sequence_forbidden(const int *moves, int depth)
{
    if (!depth) return 0;
    int last = moves[depth - 1] - 1;
    int shift = last < 3 ? 0 : (last < 6 ? 3 : 6);
    unsigned forbidden = 7U << shift;
    if (depth < 2) return forbidden;
    int length = depth < 4 ? depth : 4;
    int index = 0;
    for (int i = depth - length; i < depth; ++i)
        index = (index << 3) + index + moves[i] - 1;
    unsigned byte = length == 2 ? sequence_reject3[index] :
                    length == 3 ? sequence_reject4[index] :
                                  sequence_reject5[index];
    unsigned low = (1U << shift) - 1;
    return forbidden | (byte & low) | ((byte & ~low) << 3);
}

